solutionCode:
open class Subsystem(val name: String) {
    open fun reset() {
        println("$name: resetting subsystem")
    }
}

class ClimberSubsystem : Subsystem("Climber") {
    var height = 0.0

    override fun reset() {
        super.reset()
        height = 0.0
        println("Climber height reset to 0.0")
    }
}

